                        /* Ensure all elements inherit the color from its parent */
                        a, .w-input, .w-select, .w-tab-link, .w-nav-link, .w-nav-brand, .w-dropdown-btn, .w-dropdown-toggle, .w-slider-arrow-left, .w-slider-arrow-right, .w-dropdown-link {
