                            display: grid;
                            gap: .75rem
                        }

                        .shen .hero_list-item {
                            display: flex;
                            align-items: flex-start;
                            gap: .75rem;
                            font-size: 1rem;
                            line-height: 1.4
                        }

                        .shen .hero_list-icon {
                            width: 1rem;
                            height: 1rem;
                            flex: none;
                            margin-top: .15rem
                        }

                        .shen .hero_buttons {
                            margin-top: 2.25rem
                        }

                        .shen .hero_visual {
                            position: relative;
                            display: flex;
                            justify-content: center;
                            align-items: center;
                            min-height: 38rem
                        }

                        .shen .hero_visual-glow {
                            position: absolute;
                            width: 26rem;
                            height: 26rem;
                            border-radius: 50%;
                            background: radial-gradient(circle,rgba(199,255,190,.16) 0%,rgba(199,255,190,0) 70%);
                            filter: blur(10px)
                        }

                        .shen .chip {
                            position: absolute;
                            z-index: 3;
                            display: inline-flex;
                            align-items: center;
                            gap: .5rem;
                            padding: .625rem .875rem;
                            border-radius: .75rem;
                            background: #151b26;
                            border: 1px solid rgba(255,255,255,.1);
                            font-size: .8125rem;
                            font-weight: 600;
                            line-height: 1;
                            box-shadow: 0 12px 40px rgba(0,0,0,.4);
                            white-space: nowrap
                        }

                        .shen .chip-a {
                            top: 7rem;
                            left: calc(50% - 8.5rem);
                            transform: translateX(-100%)
                        }

                        .shen .chip-b {
                            bottom: 8.5rem;
                            left: calc(50% + 8.5rem)
                        }

                        .shen .chip-icon {
                            width: 1rem;
                            height: 1rem;
                            flex: none
                        }

                        .shen .hero_logos {
                            margin-top: 4.5rem;
                            padding-bottom: 3.5rem;
                            border-top: 1px solid rgba(255,255,255,.08);
                            padding-top: 2.5rem
                        }

                        .shen .hero_logos-label {
                            text-align: center;
                            font-size: .875rem;
                            font-weight: 600;
                            opacity: .6;
                            margin-bottom: 1.75rem
                        }

                        .shen .hero_logos-row {
                            display: flex;
                            justify-content: space-between;
                            align-items: center;
                            gap: 2rem;
                            flex-wrap: wrap
                        }

                        .shen .hero_logo {
                            height: 1.75rem;
                            width: auto;
                            opacity: .85;
                            filter: grayscale(1)
                        }

                        .shen .hero_logo.is-tall {
                            height: 2.25rem
                        }

                        .shen .phone {
                            position: relative;
                            width: 19rem;
                            height: 38.5rem;
                            border-radius: 2.75rem;
                            background: #1a212d;
                            border: 1px solid rgba(255,255,255,.14);
                            box-shadow: 0 40px 90px rgba(0,0,0,.55),inset 0 0 0 .375rem #0a0d13;
                            padding: .75rem;
                            z-index: 1
                        }

                        .shen .phone_screen {
                            width: 100%;
                            height: 100%;
                            border-radius: 2.125rem;
                            background: #0b0f16;
                            overflow: hidden;
                            position: relative;
                            display: flex;
                            flex-direction: column;
                            padding: 2.5rem 1.125rem 1.125rem
                        }

                        .shen .phone_notch {
                            position: absolute;
                            top: .625rem;
                            left: 50%;
                            transform: translateX(-50%);
                            width: 6rem;
                            height: 1.5rem;
                            border-radius: 99rem;
                            background: #0a0d13;
                            border: 1px solid rgba(255,255,255,.06)
                        }

                        .shen .phone_title {
                            font-size: 1.25rem;
                            font-weight: 600;
                            letter-spacing: -.03em;
                            margin-top: .375rem;
                            line-height: 1.15
                        }

                        .shen .phone_sub {
                            font-size: .75rem;
                            color: rgba(255,255,255,.55);
                            margin-top: .25rem
                        }

                        .shen .phone_stage {
                            position: relative;
                            flex: 1;
                            margin-top: 1rem
                        }

                        .shen .phone_scan {
                            position: absolute;
                            inset: 0;
                            display: flex;
                            flex-direction: column;
                            align-items: center;
                            justify-content: center;
                            gap: 1rem;
                            transition: opacity .5s
                        }

                        .shen .phone_scan.is-hidden {
                            opacity: 0;
                            pointer-events: none
                        }

                        .shen .phone_frame {
                            position: relative;
                            width: 11.5rem;
                            height: 13.5rem;
                            border-radius: 1.5rem;
                            background: radial-gradient(ellipse at 50% 40%,rgba(199,255,190,.10),rgba(199,255,190,0) 70%);
                            overflow: hidden
                        }

                        .shen .phone_corner {
                            position: absolute;
                            width: 1.5rem;
                            height: 1.5rem;
                            border: 2px solid #c7ffbe
                        }

                        .shen .corner-tl {
                            top: 0;
                            left: 0;
                            border-right: 0;
                            border-bottom: 0;
                            border-top-left-radius: 1rem
                        }

                        .shen .corner-tr {
                            top: 0;
                            right: 0;
                            border-left: 0;
                            border-bottom: 0;
                            border-top-right-radius: 1rem
                        }

                        .shen .corner-bl {
                            bottom: 0;
                            left: 0;
                            border-right: 0;
                            border-top: 0;
                            border-bottom-left-radius: 1rem
                        }

                        .shen .corner-br {
                            bottom: 0;
                            right: 0;
                            border-left: 0;
                            border-top: 0;
                            border-bottom-right-radius: 1rem
                        }

                        .shen .phone_face {
                            position: absolute;
                            inset: 0;
                            margin: auto;
                            width: 8rem;
                            height: 10rem;
                            opacity: .9
                        }

                        .shen .phone_scanline {
                            position: absolute;
                            left: 1rem;
                            right: 1rem;
                            height: 2px;
                            background: linear-gradient(90deg,rgba(199,255,190,0),#c7ffbe,rgba(199,255,190,0));
                            top: 10%;
                            box-shadow: 0 0 18px rgba(199,255,190,.6);
                            animation: scanline 2.2s ease-in-out infinite
                        }

                        @keyframes scanline {
                            0% {
                                top: 8%
                            }

                            50% {
                                top: 88%
                            }

                            100% {
                                top: 8%
                            }
                        }

                        .shen .phone_scan-label {
                            font-size: .8125rem;
                            font-weight: 600;
                            color: rgba(255,255,255,.85)
                        }

                        .shen .phone_progress {
                            width: 11.5rem;
                            height: .375rem;
                            border-radius: 99rem;
                            background: rgba(255,255,255,.08);
                            overflow: hidden
                        }

                        .shen .phone_progress-bar {
                            height: 100%;
                            width: 0;
                            border-radius: 99rem;
                            background: #c7ffbe;
                            transition: width 3s linear
                        }

                        .shen .phone_progress-bar.is-full {
                            width: 100%
                        }

                        .shen .phone_results {
                            position: absolute;
                            inset: 0;
                            display: flex;
                            flex-direction: column;
                            opacity: 0;
                            transform: translateY(8px);
                            transition: opacity .5s,transform .5s;
                            pointer-events: none
                        }

                        .shen .phone_results.is-visible {
                            opacity: 1;
                            transform: none;
                            pointer-events: auto
                        }

                        .shen .phone_row {
                            display: grid;
                            grid-template-columns: 1fr auto auto;
                            gap: .625rem;
                            align-items: center;
                            padding: .625rem 0;
                            border-bottom: 1px solid rgba(255,255,255,.07)
                        }

                        .shen .phone_row-name {
                            font-size: .75rem;
                            color: rgba(255,255,255,.62);
                            white-space: nowrap
                        }

                        .shen .phone_row-value {
                            font-size: 1rem;
                            font-weight: 600;
                            letter-spacing: -.02em;
                            font-variant-numeric: tabular-nums
                        }

                        .shen .phone_row-unit {
                            font-size: .6875rem;
                            font-weight: 500;
                            color: rgba(255,255,255,.5);
                            margin-left: .25rem
                        }

                        .shen .phone_delta {
                            display: inline-flex;
                            align-items: center;
                            gap: .25rem;
                            font-size: .6875rem;
                            font-weight: 600;
                            padding: .25rem .5rem;
                            border-radius: 99rem;
                            background: rgba(130,204,117,.14);
                            color: #c7ffbe;
                            white-space: nowrap;
                            min-width: 3.25rem;
                            justify-content: center
                        }

                        .shen .phone_delta.is-watch {
                            background: rgba(255,255,255,.08);
                            color: rgba(255,255,255,.7)
                        }

                        .shen .phone_cta {
                            margin-top: auto;
                            display: flex;
                            justify-content: center;
                            align-items: center;
                            height: 2.75rem;
                            border-radius: .75rem;
                            background: #c7ffbe;
                            color: #171b1a;
                            font-size: .8125rem;
                            font-weight: 600
                        }

                        .shen .phone_score {
                            display: flex;
                            align-items: center;
                            gap: .75rem;
                            padding: .625rem .75rem;
                            border-radius: .875rem;
                            background: rgba(255,255,255,.04);
                            border: 1px solid rgba(255,255,255,.08);
                            margin-bottom: .125rem
                        }

                        .shen .phone_score-ring {
                            width: 2.75rem;
                            height: 2.75rem;
                            flex: none
                        }

                        .shen .phone_score-num {
                            font-size: 1.25rem;
                            font-weight: 600;
                            letter-spacing: -.03em;
                            line-height: 1
                        }

                        .shen .phone_score-label {
                            font-size: .6875rem;
                            color: rgba(255,255,255,.6);
                            margin-top: .2rem
                        }

                        .shen .stats_head {
                            display: grid;
                            grid-template-columns: 1.1fr .9fr;
                            gap: 3rem;
                            align-items: end
                        }

                        .shen .why_grid {
                            display: grid;
                            grid-template-columns: 1fr 1fr;
                            gap: 5rem;
                            align-items: start
                        }

                        .shen .why_left {
                            max-width: 34rem
                        }

                        .shen .acc {
                            margin-top: 2.75rem
                        }

                        .shen .acc_item {
                            border-top: 1px solid rgba(255,255,255,.1)
                        }

                        .shen .acc_head {
                            width: 100%;
                            display: flex;
                            justify-content: space-between;
                            align-items: center;
                            gap: 1.5rem;
                            padding: 1.5rem 0;
                            color: #fff;
                            cursor: pointer
                        }

                        .shen .acc_title {
                            font-size: 1.125rem;
                            font-weight: 600;
                            letter-spacing: -.01em;
                            line-height: 1.3
                        }

                        .shen .acc_icon {
                            width: 1.5rem;
                            height: 1.5rem;
                            flex: none;
                            border-radius: 50%;
                            border: 1px solid rgba(255,255,255,.4);
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            transition: transform .3s,background-color .3s
                        }

                        .shen .acc_icon.is-open {
                            transform: rotate(45deg);
                            background-color: #c7ffbe;
                            border-color: #c7ffbe
                        }

                        .shen .acc_icon-svg {
                            width: .625rem;
                            height: .625rem
                        }

                        .shen .acc_icon-svg.is-open {
                            stroke: #171b1a
                        }

                        .shen .acc_body {
                            max-height: 0;
                            overflow: hidden;
                            transition: max-height .45s ease
                        }

                        .shen .acc_body.is-open {
                            max-height: 22rem
                        }

                        .shen .acc_text {
                            padding-bottom: 1.75rem;
                            opacity: .8;
                            font-size: 1rem;
                            line-height: 1.55;
                            max-width: 30rem
                        }

                        .shen .acc_mobile-visual {
                            display: none;
                            margin: 0 0 1.75rem;
                            border-radius: 1rem;
                            overflow: hidden;
                            border: 1px solid rgba(255,255,255,.08);
                            background: #0b0f16;
                            aspect-ratio: 4/3
                        }

                        .shen .acc_mobile-img {
                            width: 100%;
                            height: 100%;
                            object-fit: cover
                        }

                        .shen .why_right {
                            position: sticky;
                            top: 8rem
                        }

                        .shen .why_visual {
                            display: none;
                            border-radius: 1.5rem;
                            background: #0b0f16;
                            border: 1px solid rgba(255,255,255,.08);
                            aspect-ratio: 1/1;
                            align-items: center;
                            justify-content: center;
                            overflow: hidden;
                            padding: 0
                        }

                        .shen .why_visual.is-active {
                            display: flex;
                            animation: fadein .5s ease
                        }

                        @keyframes fadein {
                            from {
                                opacity: 0;
                                transform: translateY(6px)
                            }

                            to {
                                opacity: 1;
                                transform: none
                            }
                        }

                        .shen .why_img {
                            width: 100%;
                            height: 100%;
                            object-fit: cover;
                            object-position: center 40%
                        }

                        .shen .why_img-photo {
                            width: 100%;
                            height: 100%;
                            object-fit: cover;
                            border-radius: 1rem
                        }

                        .shen .why_visual-cover {
                            padding: 0
                        }

                        .shen .tabs_bar {
                            display: flex;
                            flex-wrap: wrap;
                            gap: .75rem;
                            margin-top: 2.5rem
                        }

                        .shen .tab_link {
                            color: #fff;
                            letter-spacing: -.02em;
                            background-color: rgba(255,255,255,.04);
                            border: 1px solid rgba(255,255,255,.1);
                            border-radius: .5rem;
                            padding: 1rem 1.5rem;
                            font-weight: 600;
                            line-height: 1.1;
                            transition: color .2s,background-color .2s;
                            font-size: 1rem
                        }

                        .shen .tab_link:hover {
                            background-color: rgba(255,255,255,.08)
                        }

                        .shen .tab_link.is-active {
                            color: #0e121a;
                            background-color: #fff;
                            border-color: #fff
                        }

                        .shen .tab_link:focus-visible {
                            outline: 2px solid #82cc75;
                            outline-offset: 2px
                        }

                        .shen .tab_pane {
                            display: none;
                            margin-top: 3rem
                        }

                        .shen .tab_pane.is-active {
                            display: grid;
                            grid-template-columns: .9fr 1.1fr;
                            gap: 4rem;
                            align-items: center;
                            animation: fadein .5s ease
                        }

                        .shen .tab_copy {
                            max-width: 30rem
                        }

                        .shen .tab_bullets {
                            margin-top: 1.75rem;
                            display: grid;
                            gap: .875rem
                        }

                        .shen .tab_bullet {
                            display: flex;
                            gap: .75rem;
                            align-items: flex-start;
                            font-size: 1rem;
                            line-height: 1.45;
                            opacity: .9
                        }

                        .shen .tab_bullet-icon {
                            width: 1.125rem;
                            height: 1.125rem;
                            flex: none;
                            margin-top: .1rem
                        }

                        .shen .tab_visual {
                            border-radius: 1.5rem;
                            background: #0b0f16;
                            border: 1px solid rgba(255,255,255,.08);
                            aspect-ratio: 4/3;
                            overflow: hidden;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            padding: 0
                        }

                        .shen .tab_visual-img {
                            width: 100%;
                            height: 100%;
                            object-fit: cover;
                            object-position: center
                        }

                        .shen .tab_visual-photo {
                            width: 100%;
                            height: 100%;
                            object-fit: cover;
                            border-radius: 1rem
                        }

                        .shen .tab_visual-cover {
                            padding: 0
                        }

                        .shen .camera {
                            background-color: #0e121a;
                            color: #fff;
                            padding-top: 6.25rem;
                            padding-bottom: 6.25rem;
                            overflow: hidden
                        }

                        .shen .camera_grid {
                            display: grid;
                            grid-template-columns: 1fr 1.1fr 1fr;
                            gap: 1.5rem;
                            align-items: center;
                            margin-top: 3.5rem
                        }

                        .shen .camera_col {
                            display: flex;
                            flex-direction: column;
                            gap: 1.5rem
                        }

                        .shen .camera_card {
                            display: flex;
                            gap: 1.25rem;
                            padding: 1.5rem;
                            border-radius: 1rem;
                            border: 1px solid rgba(255,255,255,.1);
                            background: rgba(255,255,255,.02);
                            transition: border-color .2s,background-color .2s;
                            cursor: default
                        }

                        .shen .camera_card:hover {
                            border-color: rgba(199,255,190,.4);
                            background: rgba(199,255,190,.04)
                        }

                        .shen .camera_card-icon {
                            width: 2rem;
                            height: 2rem;
                            flex: none;
                            opacity: .9
                        }

                        .shen .camera_card-title {
                            font-size: 1rem;
                            font-weight: 600;
                            letter-spacing: -.01em
                        }

                        .shen .camera_card-text {
                            margin-top: .375rem;
                            font-size: .9375rem;
                            opacity: .75;
                            line-height: 1.5
                        }

                        .shen .camera_center {
                            position: relative;
                            display: flex;
                            flex-direction: column;
                            align-items: center
                        }

                        .shen .camera_img {
                            width: 100%;
                            max-width: 26rem;
                            height: auto;
                            display: block
                        }

                        .shen .camera_img-hover {
                            position: absolute;
                            top: 0;
                            left: 50%;
                            transform: translateX(-50%);
                            width: 100%;
                            max-width: 26rem;
                            height: auto;
                            opacity: 0;
                            transition: opacity .35s;
                            pointer-events: none
                        }

                        .shen .camera_img-hover.is-visible {
                            opacity: 1
                        }

                        .shen .camera_button {
                            margin-top: -1.75rem;
                            position: relative;
                            z-index: 2
                        }

                        .shen .camera_fade {
                            position: absolute;
                            bottom: 0;
                            left: 0;
                            right: 0;
                            height: 8rem;
                            background: linear-gradient(180deg,rgba(14,18,26,0),#0e121a 85%);
                            pointer-events: none
                        }

                        .shen .proof_row {
                            display: grid;
                            grid-template-columns: 1fr 1fr;
                            gap: 5rem;
                            align-items: center
                        }

                        .shen .proof_row.is-reverse {
                            direction: rtl
                        }

                        .shen .proof_row-inner {
                            direction: ltr
                        }

                        .shen .proof_copy {
                            max-width: 30rem
                        }

                        .shen .proof_img {
                            border-radius: 1.5rem;
                            overflow: hidden;
                            background: #0e121a;
                            border: 1px solid #e3e8ef
                        }

                        .shen .proof_photo {
                            width: 100%;
                            height: 100%;
                            object-fit: cover;
                            aspect-ratio: 5/4
                        }

                        .shen .proof_badges {
                            display: flex;
                            align-items: center;
                            gap: 1rem;
                            margin-top: 2rem;
                            flex-wrap: wrap
                        }

                        .shen .proof_badge {
                            height: 3.5rem;
                            width: auto
                        }

                        .shen .proof_gap {
                            margin-top: 7rem
                        }

                        .shen .gov_grid {
                            display: grid;
                            grid-template-columns: .9fr 1.1fr;
                            gap: 5rem;
                            align-items: center
                        }

                        .shen .gov_list {
                            margin-top: 2.5rem;
                            display: grid;
                            gap: 1.75rem;
                            max-width: 26rem
                        }

