                        .shen .story {
                            padding: 1.75rem 0;
                            border-bottom: 1px solid rgba(255,255,255,.1)
                        }

                        .shen .story:first-child {
                            padding-top: .5rem
                        }

                        .shen .story_title {
                            margin-top: .5rem;
                            font-size: 1.375rem;
