                                        <div class="acc" id="whyAcc">
                                            <div class="acc_item">
                                                <button aria-expanded="true" class="acc_head" data-acc="0">
                                                    <span class="acc_title">A daily reason to come back</span>
                                                    <span class="acc_icon is-open">
                                                        <svg class="acc_icon-svg is-open" fill="none" stroke="#fff" stroke-linecap="round" stroke-width="1.6" viewbox="0 0 10 10">
                                                            <path d="M5 1v8M1 5h8"></path>
