                                                    </div>
                                                    <p class="acc_text">Steps and sleep are passive. A face scan is an act, and it returns something new every day. Offer daily health checks and users open the app because the check-in is worth 30 seconds. Apps with ihealthy inside report up to 350% higher retention.</p>
                                                </div>
