                                                    </div>
                                                    <p class="acc_text">The first scan turns a sign-up into a believer. Blood pressure, heart rate and a wellness score from a selfie camera, live, in the session they signed up in. Partners describe the demo as a clear wow. Onboarding conversion follows.</p>
