                        <section class="section section-soft">
                            <div class="container-large">
                                <div class="reveal max-w-lg">
                                    <h2 class="heading-h3">What better retention does to your numbers</h2>
                                    <p class="text-medium text-muted mt-15">Defaults use the Heartery result and an average of 10 scans per active user a month. Change them to your own baseline and see what a daily health check adds to your retained base and your scan volume.</p>
                                </div>
                                <div class="calc2 reveal">
                                    <div class="calc2_in">
                                        <div class="calc2_title">Your inputs</div>
