                                            <label class="calc2_label" for="cUsers">New users per month</label>
                                            <div class="calc2_num">
                                                <input class="calc2_num-input" id="cUsers" inputmode="numeric" min="0" step="100" type="number" value="10000"/>
                                                <span class="calc2_num-unit">users</span>
                                            </div>
                                        </div>
                                        <div class="calc2_field">
                                            <label class="calc2_label" for="cRet">
                                                Day-30 retention today <span class="calc2_value" id="cRetV">4%</span>
                                            </label>
                                            <input class="calc_range" id="cRet" max="60" min="1" step="1" type="range" value="4"/>
                                            <div class="calc2_hint">Health apps average close to 4 percent. Set your own number.</div>
                                        </div>
                                        <div class="calc2_field">
                                            <label class="calc2_label" for="cUp">
                                                Retention multiplier with a daily health check <span class="calc2_value" id="cUpV">3.5x</span>
                                            </label>
                                            <input class="calc_range" id="cUp" max="4.5" min="1.2" step="0.1" type="range" value="3.5"/>
                                            <div class="calc2_hint">Heartery reached 3.5x the health-app average. Slide down for a conservative case.</div>
                                        </div>
                                        <div class="calc2_field">
                                            <label class="calc2_label" for="cScans">
                                                Scans per active user per month <span class="calc2_value" id="cScansV">10</span>
                                            </label>
                                            <input class="calc_range" id="cScans" max="30" min="2" step="1" type="range" value="10"/>
                                        </div>
                                        <div class="calc2_ref">
                                            <span class="calc2_ref-label">Reference, Heartery</span>
                                            Day-30 retention of 13 percent, 3.5x the health-app average. 25,000 downloads and the top of the App Store rankings for hypertension care in the UK, US and Canada.
                                        </div>
                                    </div>
                                    <div class="calc2_out">
                                        <div class="calc2_out-glow"></div>
                                        <div class="calc2_hero-label">Additional retained users per cohort</div>
                                        <div class="calc2_hero-num" id="cExtra">+1 000</div>
                                        <div class="calc2_hero-sub" id="cRate">14% day-30 retention with ihealthy</div>
                                        <div class="calc2_bars">
                                            <div class="calc2_bar-row">
                                                <span class="calc2_bar-label">Today</span>
                                                <div class="calc2_bar">
                                                    <div class="calc2_bar-fill" id="cBarNow"></div>
                                                </div>
                                                <span class="calc2_bar-num" id="cNow">400</span>
                                            </div>
                                            <div class="calc2_bar-row">
                                                <span class="calc2_bar-label">With ihealthy</span>
                                                <div class="calc2_bar">
                                                    <div class="calc2_bar-fill is-green" id="cBarNew"></div>
                                                </div>
                                                <span class="calc2_bar-num is-green" id="cNew">1 400</span>
                                            </div>
                                        </div>
                                        <div class="calc2_minis">
                                            <div class="calc2_mini">
                                                <div class="calc2_mini-label">Scans per month, this cohort</div>
                                                <div class="calc2_mini-num" id="cScanOut">14 000</div>
                                                <div class="calc2_mini-sub">size your plan and pipeline for this</div>
                                            </div>
                                            <div class="calc2_mini">
                                                <div class="calc2_mini-label">Retained users, 12 cohorts</div>
                                                <div class="calc2_mini-num" id="cYear">16 800</div>
                                                <div class="calc2_mini-sub">day-30 retained users added over a year</div>
                                            </div>
                                        </div>
                                        <div class="calc2_foot">Illustrative model. The multiplier is applied to day-30 retention of a single monthly cohort and capped at 100 percent. Your baseline, onboarding and reminder strategy will change the result.</div>
                                    </div>
                                </div>
                            </div>
                        </section>
                    </div>
