                                    <div class="reveal">
                                        <h2 class="heading-h2">Fully customizable SDK. Live in days.</h2>
                                        <p class="text-medium text-muted mt-15 max-w-md">ihealthy drops into your existing app without disrupting the experience your users already know. Your brand, your flow, your data. Within days you can put a 30-second health check behind a morning reminder.</p>
                                        <div class="button-group mt-3">
                                            <a class="button" href="https://shen.ai/get-started">Get started</a>
                                            <a class="button-outline" href="https://developer.shen.ai/">Developer portal</a>
                                        </div>
                                        <div class="sdk3_platforms">iOS, Android and Web. Flutter, React Native, Capacitor and MAUI. Linux headless for kiosks and devices.</div>
                                    </div>
                                    <div class="reveal sdk2_col">
                                        <div class="code">
                                            <div class="code_head">
                                                <span class="code_dots">
                                                    <span class="code_dot"></span>
                                                    <span class="code_dot"></span>
                                                    <span class="code_dot"></span>
                                                </span>
                                                <span>scan.js, Web SDK</span>
                                            </div>
                                            <pre class="code_pre">
                                                <span class="code_k">import</span>
                                                CreateShenaiSDK, { InitializationResult } <span class="code_k">from</span>
                                                <span class="code_s">"@shenai/sdk"</span>
                                                <span class="code_k">const</span>
                                                shenai = <span class="code_k">await</span>
                                                CreateShenaiSDK()

shenai.initialize(API_KEY, USER_ID, {
  language: <span class="code_s">"pl"</span>
                                                ,                    <span class="code_c">// one of 24 languages</span>
                                                hideShenaiLogo: <span class="code_k">true</span>
                                                ,              <span class="code_c">// your brand, not ours</span>
                                                customColorTheme: brandTheme,      <span class="code_c">// colours from your design system</span>
                                                eventCallback: (event) =&gt;{
    <span class="code_k">if</span>
                                                (event === <span class="code_s">"MEASUREMENT_FINISHED"</span>
                                                ) {
      <span class="code_k">const</span>
                                                r = shenai.getMeasurementResults()
      saveCheckIn(r.heart_rate_bpm, r.systolic_blood_pressure_mmhg,
                  r.hrv_sdnn_ms, r.stress_index, r.bmi_kg_per_m2)
    }
  }
}, (result) =&gt;{
  <span class="code_k">if</span>
                                                (result !== InitializationResult.OK) handleInitError(result)
})
                                            </pre>
