                                            <a class="arrow-link text-white story_link" href="https://shen.ai/customer-story/closing-the-vitals-gap-uare-brings-universal-vitals-to-their-wellbeing-platform">
                                                Learn more 
                                                <svg class="arrow-icon" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" viewbox="0 0 12 12">
