                    <script>
                        (function() {
                            if (window.__shenRT)
                                return;
                            window.__shenRT = 1;
                            var D = document;
                            function A(s, r) {
                                return Array.prototype.slice.call((r || D).querySelectorAll(s));
                            }
                            function up(e, s) {
                                return e && e.closest ? e.closest(s) : null;
                            }
                            function sec(e) {
                                return up(e, 'section') || up(e, '.shen') || D;
                            }
                            function tog(e, c, on) {
                                if (e)
                                    e.classList.toggle(c, !!on);
                            }
                            function ico(h, sel, c, on) {
                                A(sel, h).forEach(function(e) {
                                    tog(e, c, on);
                                    A('svg', e).forEach(function(s) {
                                        tog(s, c, on);
                                    });
                                });
                            }
                            function show(r, i) {
                                A('[data-show]', r).forEach(function(x) {
                                    var on = x.getAttribute('data-show') === i;
                                    tog(x, 'is-active', on);
                                    tog(x.querySelector('.show_item-kpi'), 'is-active', on);
                                });
                                A('[data-show-notif]', r).forEach(function(x) {
                                    tog(x, 'is-active', x.getAttribute('data-show-notif') === i);
                                });
                                A('[data-show-why]', r).forEach(function(x) {
                                    tog(x, 'is-active', x.getAttribute('data-show-why') === i);
                                });
                                A('[data-show-dot]', r).forEach(function(x) {
                                    tog(x, 'is-active', x.getAttribute('data-show-dot') === i);
                                });
                            }
                            D.addEventListener('click', function(e) {
                                var t = e.target, n;
                                if ((n = up(t, '[data-acc]'))) {
                                    var r = sec(n)
                                      , i = n.getAttribute('data-acc');
                                    A('[data-acc]', r).forEach(function(h) {
                                        var on = h.getAttribute('data-acc') === i;
                                        tog(h.querySelector('.acc_icon'), 'is-open', on);
                                        ico(h, '.acc_icon-svg', 'is-open', on);
                                        h.setAttribute('aria-expanded', on ? 'true' : 'false');
                                    });
                                    A('[data-acc-body]', r).forEach(function(b) {
                                        tog(b, 'is-open', b.getAttribute('data-acc-body') === i);
                                    });
                                    A('[data-visual]', r).forEach(function(v) {
                                        tog(v, 'is-active', v.getAttribute('data-visual') === i);
                                    });
                                    return;
                                }
                                if ((n = up(t, '[data-tab]'))) {
                                    var r = sec(n)
                                      , i = n.getAttribute('data-tab');
                                    A('[data-tab]', r).forEach(function(x) {
                                        tog(x, 'is-active', x.getAttribute('data-tab') === i);
                                    });
                                    A('[data-pane]', r).forEach(function(x) {
                                        tog(x, 'is-active', x.getAttribute('data-pane') === i);
                                    });
                                    return;
                                }
                                if ((n = up(t, '[data-mp]'))) {
                                    var r = sec(n)
                                      , i = n.getAttribute('data-mp');
                                    A('[data-mp]', r).forEach(function(x) {
                                        var on = x.getAttribute('data-mp') === i;
                                        tog(x, 'is-active', on);
                                        tog(x.querySelector('.mp_tab-badge'), 'is-active', on);
                                    });
                                    A('[data-mp-pane]', r).forEach(function(x) {
                                        tog(x, 'is-active', x.getAttribute('data-mp-pane') === i);
                                    });
                                    return;
                                }
                                if ((n = up(t, '[data-faq]'))) {
                                    var r = sec(n)
                                      , i = n.getAttribute('data-faq')
                                      , was = n.getAttribute('aria-expanded') === 'true';
                                    A('[data-faq]', r).forEach(function(x) {
                                        var on = x.getAttribute('data-faq') === i && !was;
                                        x.setAttribute('aria-expanded', on ? 'true' : 'false');
                                        tog(x.querySelector('.faq_icon'), 'is-open', on);
                                        ico(x, '.faq_icon-svg', 'is-open', on);
                                    });
                                    A('[data-faq-a]', r).forEach(function(a) {
                                        tog(a, 'is-open', a.getAttribute('data-faq-a') === i && !was);
                                    });
                                    return;
                                }
                                if ((n = up(t, '.testi_btn'))) {
                                    var r = sec(n)
                                      , sl = A('[data-slide]', r);
                                    if (!sl.length)
                                        return;
                                    var cur = 0;
                                    sl.forEach(function(s, k) {
                                        if (s.classList.contains('is-active'))
                                            cur = k;
                                    });
                                    var back = /prev/i.test(n.id || '') || /poprz|prev/i.test(n.getAttribute('aria-label') || '');
                                    var nx = (cur + (back ? -1 : 1) + sl.length) % sl.length;
                                    sl.forEach(function(s, k) {
                                        tog(s, 'is-active', k === nx);
                                    });
                                    return;
                                }
                                if ((n = up(t, '[data-show]')) || (n = up(t, '[data-show-dot]'))) {
                                    var r = up(n, '.show') || sec(n);
                                    show(r, n.getAttribute('data-show') || n.getAttribute('data-show-dot'));
                                    r.__p = 1;
                                    return;
                                }
                            });
                            D.addEventListener('mouseover', function(e) {
                                var c = up(e.target, '[data-hover]');
                                if (!c)
                                    return;
                                var r = sec(c)
                                  , i = c.getAttribute('data-hover');
                                A('[data-hover-img]', r).forEach(function(m) {
                                    tog(m, 'is-visible', m.getAttribute('data-hover-img') === i);
                                });
                            });
                            D.addEventListener('mouseout', function(e) {
                                var c = up(e.target, '[data-hover]');
                                if (!c)
                                    return;
                                var r = sec(c);
                                A('[data-hover-img]', r).forEach(function(m) {
                                    tog(m, 'is-visible', false);
                                });
                            });
                            function num(v) {
                                return Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
                            }
                            function paint(r) {
                                if (!r)
                                    return;
                                var mn = parseFloat(r.min)
                                  , mx = parseFloat(r.max)
                                  , v = parseFloat(r.value);
                                var p = ((v - mn) / (mx - mn)) * 100;
                                r.style.background = 'linear-gradient(90deg,#52b441 ' + p + '%,#e3e8ef ' + p + '%)';
                            }
                            function id(x) {
                                return D.getElementById(x);
                            }
                            function calcRet() {
                                var u = id('cUsers');
                                if (!u)
                                    return;
                                var ret = +id('cRet').value
                                  , up2 = parseFloat(id('cUp').value)
                                  , sc = +id('cScans').value;
                                var users = Math.max(0, parseInt(u.value, 10) || 0)
                                  , now = users * ret / 100
                                  , nr = Math.min(100, ret * up2)
                                  , ws = users * nr / 100;
                                id('cRetV').textContent = ret + '%';
                                id('cUpV').textContent = up2.toFixed(1) + 'x';
                                id('cScansV').textContent = sc;
                                id('cNow').textContent = num(now);
                                id('cNew').textContent = num(ws);
                                id('cExtra').textContent = '+' + num(ws - now);
                                id('cRate').textContent = Math.round(nr) + '% day-30 retention with ihealthy';
                                id('cScanOut').textContent = num(ws * sc);
                                id('cYear').textContent = num((ws - now) * 12);
                                var mv = Math.max(ws, 1);
                                id('cBarNow').style.width = Math.max(2, (now / mv) * 100) + '%';
                                id('cBarNew').style.width = '100%';
                                [id('cRet'), id('cUp'), id('cScans')].forEach(paint);
                            }
                            function calcCost() {
                                var n = id('sN');
                                if (!n)
                                    return;
                                var c = parseFloat(id('sC').value) || 0
                                  , s = +id('sS').value
                                  , pr = parseFloat(id('sP').value) || 0;
                                var q = Math.max(0, parseInt(n.value, 10) || 0)
                                  , now = q * c
                                  , mv = q * s / 100
                                  , ws = (q - mv) * c + mv * pr;
                                id('sSV').textContent = s + '%';
                                id('sNow').textContent = num(now);
                                id('sNew').textContent = num(ws);
                                id('sSave').textContent = num(now - ws);
                                id('sMoved').textContent = num(mv);
                                if (id('sKept'))
                                    id('sKept').textContent = num(q - mv);
                                if (id('sBlend'))
                                    id('sBlend').textContent = q ? (Math.round((ws / q) * 10) / 10).toString().replace('.', ',') : '0';
                                if (id('sBase'))
                                    id('sBase').textContent = (Math.round(c * 10) / 10).toString().replace('.', ',');
                                id('sBarOld').style.width = '100%';
                                id('sBarNew').style.width = Math.max(2, (ws / Math.max(now, 1)) * 100) + '%';
                                paint(id('sS'));
                            }
                            D.addEventListener('input', function(e) {
                                if (up(e.target, '.calc2')) {
                                    calcRet();
                                    calcCost();
                                }
                            });
                            function fit() {
                                var w = D.documentElement.clientWidth;
                                A('.wf-bleed').forEach(function(e) {
                                    e.style.marginLeft = '0';
                                    e.style.marginRight = '0';
                                    e.style.width = 'auto';
                                    var l = e.getBoundingClientRect().left;
                                    e.style.marginLeft = (-l) + 'px';
                                    e.style.width = w + 'px';
                                });
                            }
                            function init() {
                                fit();
                                calcRet();
                                calcCost();
                                A('.show').forEach(function(r) {
                                    if (r.__i)
                                        return;
                                    r.__i = 1;
                                    show(r, '0');
                                    r.addEventListener('mouseenter', function() {
                                        r.__p = 1;
                                    });
                                    r.addEventListener('mouseleave', function() {
                                        r.__p = 0;
                                    });
                                    setInterval(function() {
                                        if (r.__p)
                                            return;
                                        var it = A('[data-show]', r);
                                        if (!it.length)
                                            return;
                                        var c = 0;
                                        it.forEach(function(x, k) {
                                            if (x.classList.contains('is-active'))
                                                c = k;
                                        });
                                        show(r, String((c + 1) % it.length));
                                    }, 6000);
                                });
                                A('.phone_stage').forEach(function(st) {
                                    if (st.__i)
                                        return;
                                    st.__i = 1;
                                    var sc = st.querySelector('.phone_scan')
                                      , rs = st.querySelector('.phone_results')
                                      , bar = st.querySelector('.phone_progress-bar');
                                    if (!sc || !rs)
                                        return;
                                    function loop() {
                                        tog(sc, 'is-hidden', false);
                                        tog(rs, 'is-visible', false);
                                        tog(bar, 'is-full', false);
                                        setTimeout(function() {
                                            tog(bar, 'is-full', true);
                                        }, 150);
                                        setTimeout(function() {
                                            tog(sc, 'is-hidden', true);
                                            tog(rs, 'is-visible', true);
                                        }, 3400);
                                        setTimeout(loop, 12500);
                                    }
                                    setTimeout(loop, 600);
                                });
                                A('.formv').forEach(function(f) {
                                    if (f.__i)
                                        return;
                                    f.__i = 1;
                                    var m = A('.formv_meas', f)
                                      , c = f.querySelector('#formCount');
                                    m.forEach(function(x, k) {
                                        setTimeout(function() {
                                            tog(x, 'is-in', true);
                                            if (c)
                                                c.textContent = String(k + 1);
                                        }, 900 + k * 700);
                                    });
                                });
                            }
                            init();
                            window.addEventListener('load', init);
                            window.addEventListener('resize', fit);
                            setTimeout(init, 400);
                            setTimeout(init, 1500);
                        }
                        )();
                    </script>
